class METPurchCancelUIBuilder extends SysOperationAutomaticUIBuilder
{
    private DialogField reasonCodeDialogField;

}

Method.Source:
/// <summary>
/// postBuild to override lookup method
/// </summary>
public void postBuild()
{
    super();

    reasonCodeDialogField = this.bindInfo().getDialogField(this.dataContractObject(), methodStr(METPurchCancelContract, parmReasonCode));
    reasonCodeDialogField.registerOverrideMethod(methodStr(FormStringControl, lookup), methodStr(METPurchCancelUIBuilder, lookupReasonCode), this);
}

/// <summary>
/// lookupReasonCode
/// </summary>
/// <param name = "_formStringControl">_formStringControl</param>
private void lookupReasonCode(FormStringControl _formStringControl)
{
    Query query = new Query();
    QueryBuildDataSource qbds;
    SysTableLookup sysTableLookup;

    sysTableLookup = SysTableLookup::newParameters(tableNum(METPOChangeReasonCodeSetup), _formStringControl);

    qbds = query.addDataSource(tableNum(METPOChangeReasonCodeSetup));

    sysTableLookup.addLookupfield(fieldNum(METPOChangeReasonCodeSetup, ChangeReasonCode), true);
    sysTableLookup.addLookupfield(fieldNum(METPOChangeReasonCodeSetup, ChangeReasonDesc));
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
